class Solution {
    int gcd(int a, int b) {
        if (a < 0) a = -a;
        if (b < 0) b = -b;
        while (b) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
public:
    int maxPoints(vector<vector<int>>& points) {
        int n = points.size();
        if (n <= 2) return n;
        int ans = 0;
        for (int i = 0; i < n; i++) {
            unordered_map<long long, int> cnt;
            int localMax = 0;
            for (int j = i + 1; j < n; j++) {
                int dx = points[j][0] - points[i][0];
                int dy = points[j][1] - points[i][1];
                int g = gcd(dx, dy);
                dx /= g;
                dy /= g;
                if (dx < 0 || (dx == 0 && dy < 0)) {
                    dx = -dx;
                    dy = -dy;
                }
                long long key = (long long)dx * 40001 + (dy + 20000);
                cnt[key]++;
                localMax = max(localMax, cnt[key]);
            }
            ans = max(ans, localMax + 1);
        }
        return ans;
    }
};
